UPDATE quant_strategy_entry_guard SET order_id = #{orderId}
WHERE instance_id = #{instanceId}
  AND credential_id = #{credentialId}
  AND symbol = #{symbol}
  AND kline_open_time = #{openTime}
  AND (order_id IS NULL OR order_id = #{orderId})

